function openCustomerReschedule(id){const booking=db.bookings.find(b=>b.id===id);if(!booking||booking.status!=='confirmed')return toast('仅尚未到店的预约可以改期');if(booking.project!=='cut'){panel='contact';render();return;}const original={...booking},modal=document.createElement('div');let newDay=booking.day<today()?today():booking.day,newStart=null;modal.className='modal-backdrop';modal.innerHTML=`<section class="profile-modal reschedule-modal" role="dialog" aria-modal="true" aria-label="更改预约时间"><div class="view-title"><h2>更改预约时间</h2><button class="secondary" type="button" data-reschedule-close>关闭</button></div><p>原预约：${esc(original.day)} ${time(original.start)} · ${esc(original.title)} · ${original.duration}分钟</p><label>选择新日期<input type="date" min="${today()}" value="${newDay}" data-reschedule-date></label><p class="muted">米色可预约，深绿色不可预约。改期保留本次服务时长，确认后同步到商家日程。</p><div class="slots" data-reschedule-slots></div><p data-reschedule-status role="status"></p><button type="button" data-reschedule-save disabled>确认改期</button></section>`;document.body.appendChild(modal);const status=modal.querySelector('[data-reschedule-status]'),saveButton=modal.querySelector('[data-reschedule-save]');
 const update=()=>{newStart=null;saveButton.disabled=true;const hours=daySchedule(newDay),slots=[];for(let start=hours.open;start<hours.close;start+=SalonCore.slotInterval(db)){const available=canBook(newDay,start,original.duration,id),unchanged=newDay===original.day&&start===original.start;slots.push(`<button type="button" data-new-time="${start}" class="${available?'':'unavailable'}" ${available?'':'disabled'} aria-pressed="false">${time(start)}<span>${unchanged?'原时间':available?'可预约':'不可预约'}</span></button>`);}modal.querySelector('[data-reschedule-slots]').innerHTML=slots.join('');status.textContent=slots.length?'请选择新的到店时间。':'当天没有开放时间，请选择其他日期。';};
 modal.querySelector('[data-reschedule-close]').onclick=()=>modal.remove();modal.querySelector('[data-reschedule-date]').onchange=e=>{if(!e.target.value)return;newDay=e.target.value;update();};modal.querySelector('[data-reschedule-slots]').onclick=e=>{const b=e.target.closest('[data-new-time]');if(!b||b.disabled)return;newStart=+b.dataset.newTime;for(const slot of modal.querySelectorAll('[data-new-time]')){const chosen=slot===b;slot.classList.toggle('chosen',chosen);slot.setAttribute('aria-pressed',String(chosen));}saveButton.disabled=newDay===original.day&&newStart===original.start;status.textContent='新时间：'+newDay+' '+time(newStart)+'—'+time(newStart+original.duration);};
 saveButton.onclick=async()=>{if(newStart===null||saveButton.disabled)return;saveButton.disabled=true;status.textContent='正在保存改期…';try{if(globalThis.SalonNetwork?.ready)await SalonNetwork.reschedule(original,newDay,newStart);else{const current=db.bookings.find(b=>b.id===id);if(!current||current.status!=='confirmed'||current.day!==original.day||current.start!==original.start)throw Error('原预约已变化，请重新打开');if(!canBook(newDay,newStart,current.duration,id))throw Error('新时间无法安排，原预约保持不变');const next={...current,day:newDay,start:newStart};delete next.staffId;Object.assign(current,SalonCore.allocate(db,next,id));save();}modal.remove();panel='records';render();toast('改期成功，商家日程已同步');}catch(err){status.textContent='改期未完成：'+err.message+'。原预约没有取消。';saveButton.disabled=false;}};
 update();}